def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(expr: str) -> list[tuple[str, str | int]]:
        tokens: list[tuple[str, str | int]] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and expr[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(expr[i:j])))
                i = j
            elif ch.isalpha():
                j = i + 1
                while j < n and expr[j].isalnum():
                    j += 1
                word = expr[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif ch == "<":
                if i + 1 < n and expr[i + 1] == ">":
                    tokens.append(("OP", "<>"))
                    i += 2
                elif i + 1 < n and expr[i + 1] == "=":
                    tokens.append(("OP", "<="))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and expr[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        return tokens

    def parse(tokens: list[tuple[str, str | int]]) -> tuple:
        pos = 0
        n = len(tokens)

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while pos < n and tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("binop", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while pos < n and tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("binop", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            neg = False
            while pos < n and tokens[pos][0] == "-":
                pos += 1
                neg = not neg
            node = parse_atom()
            return ("neg", node) if neg else node

        def parse_atom() -> tuple:
            nonlocal pos
            tok_type, tok_val = tokens[pos]
            if tok_type == "NUM":
                pos += 1
                return ("num", tok_val)
            if tok_type == "CELL":
                pos += 1
                return ("cell", tok_val)
            if tok_type == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            func = tok_val
            pos += 2
            if func == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_node = parse_expr()
                pos += 1
                else_node = parse_expr()
                pos += 1
                return ("if", op, left, right, then_node, else_node)
            args = []
            while True:
                if (
                    tokens[pos][0] == "CELL"
                    and pos + 1 < n
                    and tokens[pos + 1][0] == ":"
                ):
                    c1_name = str(tokens[pos][1])
                    c2_name = str(tokens[pos + 2][1])
                    pos += 3
                    c1, r1 = ord(c1_name[0]), int(c1_name[1:])
                    c2, r2 = ord(c2_name[0]), int(c2_name[1:])
                    if c1 > c2:
                        c1, c2 = c2, c1
                    if r1 > r2:
                        r1, r2 = r2, r1
                    args.append(("range", c1, r1, c2, r2))
                else:
                    args.append(parse_expr())
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return ("agg", func, args)

        return parse_expr()

    memo: dict[str, int | str] = {}
    ast: dict[str, tuple] = {}
    for name, content in cells.items():
        s = content.strip()
        if s.startswith("="):
            ast[name] = parse(tokenize(s[1:]))
        else:
            memo[name] = int(s)

    in_progress: set[str] = set()
    cols = [chr(c) for c in range(65, 91)]

    for root_name in cells:
        if root_name in memo:
            continue

        stack: list[tuple] = []
        evaluating = True
        node: tuple = ("cell", root_name)
        val: int | str | None = None

        while True:
            if evaluating:
                kind = node[0]
                if kind == "num":
                    val = node[1]
                    evaluating = False
                elif kind == "cell":
                    name = node[1]
                    if name in memo:
                        val = memo[name]
                        evaluating = False
                    elif name not in cells:
                        val = 0
                        evaluating = False
                    elif name in in_progress:
                        val = "#CYCLE!"
                        evaluating = False
                    else:
                        in_progress.add(name)
                        stack.append(("cell_done", name))
                        node = ast[name]
                elif kind == "neg":
                    stack.append(("neg_done",))
                    node = node[1]
                elif kind == "binop":
                    _, op, left, right = node
                    stack.append(("binop_left", op, right))
                    node = left
                elif kind == "if":
                    _, op, left, right, then_n, else_n = node
                    stack.append(("if_left", op, right, then_n, else_n))
                    node = left
                else:  # "agg"
                    _, func, args = node
                    acc = 0 if func == "SUM" else None
                    stack.append(("agg_step", func, args, 0, -1, -1, acc))
                    val = None
                    evaluating = False
            else:
                if not stack:
                    break
                frame = stack.pop()
                ftype = frame[0]
                if ftype == "cell_done":
                    _, name = frame
                    in_progress.remove(name)
                    memo[name] = val  # type: ignore[assignment]
                elif ftype == "neg_done":
                    if not isinstance(val, str):
                        val = -val  # type: ignore[operator]
                elif ftype == "binop_left":
                    _, op, right = frame
                    if not isinstance(val, str):
                        stack.append(("binop_right", op, val))
                        node = right
                        evaluating = True
                elif ftype == "binop_right":
                    _, op, left_val = frame
                    if not isinstance(val, str):
                        assert isinstance(val, int) and isinstance(left_val, int)
                        if op == "+":
                            val = left_val + val
                        elif op == "-":
                            val = left_val - val
                        elif op == "*":
                            val = left_val * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(left_val) // abs(val)
                                if (left_val < 0) ^ (val < 0):
                                    q = -q
                                val = q
                elif ftype == "if_left":
                    _, op, right, then_n, else_n = frame
                    if not isinstance(val, str):
                        stack.append(("if_right", op, val, then_n, else_n))
                        node = right
                        evaluating = True
                elif ftype == "if_right":
                    _, op, left_val, then_n, else_n = frame
                    if not isinstance(val, str):
                        assert isinstance(val, int) and isinstance(left_val, int)
                        if op == "=":
                            cond = left_val == val
                        elif op == "<>":
                            cond = left_val != val
                        elif op == "<":
                            cond = left_val < val
                        elif op == "<=":
                            cond = left_val <= val
                        elif op == ">":
                            cond = left_val > val
                        else:
                            cond = left_val >= val
                        node = then_n if cond else else_n
                        evaluating = True
                else:  # "agg_step"
                    _, func, args, arg_idx, r, c, acc = frame
                    if val is not None:
                        if isinstance(val, str):
                            continue
                        if func == "SUM":
                            acc += val
                        elif acc is None or (val < acc if func == "MIN" else val > acc):
                            acc = val

                    while arg_idx < len(args):
                        arg = args[arg_idx]
                        if arg[0] == "range":
                            _, c1, r1, c2, r2 = arg
                            if r == -1:
                                r, c = r1, c1
                            paused = False
                            while r <= r2:
                                cname = cols[c - 65] + str(r)
                                c += 1
                                if c > c2:
                                    c = c1
                                    r += 1
                                if cname in cells:
                                    if cname in memo:
                                        cv = memo[cname]
                                        if isinstance(cv, str):
                                            val = cv
                                            paused = True
                                            break
                                        if func == "SUM":
                                            acc += cv
                                        elif acc is None or (
                                            cv < acc if func == "MIN" else cv > acc
                                        ):
                                            acc = cv
                                    elif cname in in_progress:
                                        val = "#CYCLE!"
                                        paused = True
                                        break
                                    else:
                                        stack.append(
                                            ("agg_step", func, args, arg_idx, r, c, acc)
                                        )
                                        node = ("cell", cname)
                                        evaluating = True
                                        paused = True
                                        break
                            if paused:
                                break
                            arg_idx += 1
                            r = -1
                        else:
                            stack.append(("agg_step", func, args, arg_idx + 1, -1, -1, acc))
                            node = arg
                            evaluating = True
                            break
                    else:
                        val = 0 if acc is None else acc
                        evaluating = False

    return {name: memo[name] for name in cells}
